    "catalogo.proteina.intro": "Cada proteína especial ocupa un número fijo de comidas por semana o por ciclo de 2 semanas. El pollo no tiene regla propia: rellena todo lo que sobra, así que es la base natural del menú.",
    "catalogo.carbo.intro": "Se sortean por probabilidad en cada comida que no sea un plato cerrado. Los porcentajes deberían sumar 100%.",
    "catalogo.verdura.intro": "Se sortean por probabilidad, igual que los carbohidratos. Los porcentajes deberían sumar 100%.",
    "catalogo.grasa.intro": "Opciones de grasa (aceite, aguacate, frutos secos, queso...). Cuando el motor de objetivos necesite completar grasa en una comida, sorteará entre estas por probabilidad — si no añades ninguna, seguirá usando aceite de oliva por defecto.",
    "catalogo.desayuno.intro": "Opciones completas de desayuno, sin combinar con nada más. Cada 2 semanas (14 desayunos) se reparte exactamente según estos porcentajes, mezclando el orden al azar. Los porcentajes deberían sumar 100%.",
    "catalogo.mediaManana.intro": "Opciones completas de media mañana, sin combinar con nada más. Cada 2 semanas (14 comidas) se reparte exactamente según estos porcentajes, mezclando el orden al azar. Los porcentajes deberían sumar 100%.",
    "catalogo.merienda.intro": "Opciones completas de merienda, sin combinar con nada más. Cada 2 semanas (14 meriendas) se reparte exactamente según estos porcentajes, mezclando el orden al azar. Los porcentajes deberían sumar 100%.",
    "catalogo.cerrado.intro": "Van enteros, sin combinar con carbo ni verdura. El grupo entero aparece con la frecuencia del bloque; dentro, se sortea cuál plato toca.",
    "catalogo.especial.intro": "No compiten por un hueco de proteína: se superponen sobre la comida que toque ese día.",
    "catalogo.especial.extraNote": "Modificador: mezcla 50/50 con el carbo del día",
