    // Páginas legales sueltas (privacidad.html/terminos.html) — no forman parte de la SPA de
    // app.jsx, pero comparten el mismo diccionario: leen el idioma guardado con leerIdiomaGuardado()
    // y tienen su propio selector ES/EN, igual que la bienvenida (ver auth-bootstrap.jsx).
    "privacidad.titulo": "Política de privacidad — FoodDraft",
    "privacidad.actualizado": "Última actualización: 25 de octubre de 2026",
    "privacidad.responsableHeader": "Responsable del tratamiento",
    "privacidad.responsableTexto": "Pablo Díaz Blanco, España.<br />Contacto: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "privacidad.datosHeader": "Qué datos se recogen",
    "privacidad.datosCuenta": "<strong>Cuenta</strong>: email y, si inicias sesión con Google, tu foto de perfil.",
    "privacidad.datosPerfil": "<strong>Datos de perfil</strong>: edad, altura, peso, sexo, nivel de actividad y entrenamientos habituales, objetivo nutricional.",
    "privacidad.datosSeguimiento": "<strong>Seguimiento</strong>: historial de pesadas, menús generados, catálogo de alimentos y platos que crees, lo que apuntas en tu despensa y tus entrenamientos.",
    "privacidad.datosFotos": "<strong>Fotos, despensa y textos enviados a la IA</strong>: si usas el lector por foto, la imagen se envía a Gemini (Google) para leer los datos nutricionales. Si usas «¿Qué cocino?», se envía a Gemini lo que decidas incluir: una foto de ingredientes, el texto que escribas y, si dejas marcada la casilla, la lista de lo que tienes en la despensa (el nombre de cada alimento y una cantidad aproximada). Solo se envía para preparar la respuesta y <strong>no se almacena</strong> en ningún servidor de FoodDraft — se descarta tras procesarlo.",
    "privacidad.paraQueHeader": "Para qué se usan",
    "privacidad.paraQueTexto": "Únicamente para prestar el servicio: generar tus menús, calcular tus objetivos nutricionales y llevar tu seguimiento de peso. No se usan con fines publicitarios ni se venden a terceros.",
    "privacidad.baseLegalHeader": "Base legal",
    "privacidad.baseLegalTexto": "La ejecución del servicio que solicitas al crear una cuenta (art. 6.1.b RGPD) y, en el caso de las fotos, de lo que envías a la IA y de los datos del período (datos de salud), tu consentimiento explícito (art. 6.1.a y 9.2.a RGPD) al usar esas funciones de forma voluntaria.",
    "privacidad.conQuienHeader": "Con quién se comparten",
    "privacidad.conQuienFirebase": "<strong>Google Firebase</strong> (autenticación, base de datos, protección anti-abuso, avisos y, vía Gemini, lectura de fotos y generación de recetas), como encargado del tratamiento, con sus propias garantías de seguridad y transferencia internacional de datos.",
    "privacidad.conQuienStripe": "<strong>Stripe</strong>, únicamente si contratas una suscripción de pago, para gestionar el cobro (no se le comparten datos de salud, solo lo necesario para procesar el pago).",
    "privacidad.conQuienNadie": "No se comparte nada con nadie más.",
    "privacidad.cuantoTiempoHeader": "Cuánto tiempo se conservan",
    "privacidad.cuantoTiempoTexto": "Mientras tu cuenta exista. Puedes eliminarla por completo, junto con todos tus datos, desde la app en cualquier momento (Ajustes → Eliminar cuenta).",
    "privacidad.derechosHeader": "Tus derechos",
    "privacidad.derechosTexto": "Acceso, rectificación, supresión, oposición, portabilidad y limitación del tratamiento. Puedes ejercerlos eliminando tu cuenta directamente desde la app, o escribiendo a <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>.",
    "privacidad.seguridadHeader": "Seguridad",
    "privacidad.seguridadTexto": "Los datos viajan cifrados y están protegidos por reglas de acceso que garantizan que cada persona solo puede ver y modificar los suyos.",
    "privacidad.cambiosHeader": "Cambios en esta política",
    "privacidad.cambiosTexto": "Si esta política cambia de forma relevante, se avisará dentro de la propia app.",
    "privacidad.volver": "← Volver a FoodDraft",

    "terminos.titulo": "Términos de uso — FoodDraft",
    "terminos.actualizado": "Última actualización: 14 de octubre de 2026",
    "terminos.quienesSomosHeader": "Quiénes somos",
    "terminos.quienesSomosTexto": "FoodDraft es un servicio operado por Pablo Díaz Blanco, España.<br />Contacto: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "terminos.queEsHeader": "Qué es el servicio",
    "terminos.queEsTexto": "FoodDraft genera menús semanales a partir de tus propios platos, calcula objetivos nutricionales orientativos y lleva un seguimiento de tu peso. <strong>Los cálculos de calorías, macros y objetivos son estimaciones orientativas</strong> basadas en fórmulas de uso general (como Mifflin-St Jeor) — no sustituyen el consejo de un médico, nutricionista o profesional de la salud. Ante cualquier duda o condición médica, consulta siempre con un profesional.",
    "terminos.tuCuentaHeader": "Tu cuenta",
    "terminos.tuCuentaTexto": "El servicio es de uso personal. Eres responsable de mantener segura tu contraseña y de la actividad de tu cuenta. Puedes eliminarla por completo en cualquier momento desde la app (Ajustes → Eliminar cuenta).",
    "terminos.suscripcionHeader": "Suscripción de pago",
    "terminos.suscripcionTexto": "Si contratas la versión de pago, el cobro se gestiona a través de Stripe. Puedes cancelar en cualquier momento desde el portal de gestión de tu suscripción — la cancelación se aplica al final del periodo ya pagado, sin cargos adicionales. Al cancelar, las funciones premium dejan de estar disponibles, pero tus datos y el resto de la app siguen intactos.",
    "terminos.responsabilidadHeader": "Responsabilidad",
    "terminos.responsabilidadTexto": "Usas la app bajo tu propia responsabilidad. No garantizamos resultados concretos de salud, peso o composición corporal — la app es una herramienta de apoyo para organizar tu alimentación, no un tratamiento médico. En la medida permitida por la ley, no se asume responsabilidad por decisiones tomadas a partir de la información que ofrece la app.",
    "terminos.usoIndebidoHeader": "Uso indebido",
    "terminos.usoIndebidoTexto": "Nos reservamos el derecho de suspender o cancelar una cuenta en caso de uso indebido del servicio (por ejemplo, intentos de abuso de las funciones que usan inteligencia artificial, o acceso no autorizado a cuentas de terceros).",
    "terminos.propiedadHeader": "Propiedad intelectual",
    "terminos.propiedadTexto": "FoodDraft — la aplicación, su código, su diseño y sus textos — es propiedad de Pablo Díaz Blanco y está protegida por la legislación de propiedad intelectual. Todos los derechos reservados. Se te concede un derecho personal, limitado, revocable y no exclusivo para usar la app mientras tengas cuenta; eso no incluye copiar, modificar, redistribuir ni usar su código o sus contenidos para crear otro servicio. Que el código fuente sea visible públicamente no supone ninguna licencia de uso. Los datos que introduces (tus platos, tus notas, tu perfil) siguen siendo tuyos.",
    "terminos.cambiosHeader": "Cambios en estos términos",
    "terminos.cambiosTexto": "Si cambian de forma relevante, se avisará dentro de la propia app.",
    "terminos.leyAplicableHeader": "Ley aplicable",
    "terminos.leyAplicableTexto": "Estos términos se rigen por la legislación española.",
    "terminos.volver": "← Volver a FoodDraft",

