    "catalogo.proteina.intro": "Each special protein takes up a fixed number of meals per week or per 2-week cycle. Chicken has no rule of its own: it fills in whatever's left, so it's the natural base of the menu.",
    "catalogo.carbo.intro": "Drawn by probability for any meal that isn't a closed dish. The percentages should add up to 100%.",
    "catalogo.verdura.intro": "Drawn by probability, same as carbs. The percentages should add up to 100%.",
    "catalogo.grasa.intro": "Fat options (oil, avocado, nuts, cheese...). When the goals engine needs to top up fat in a meal, it'll draw among these by probability — if you haven't added any, it'll keep using olive oil by default.",
    "catalogo.desayuno.intro": "Complete breakfast options, not combined with anything else. Every 2 weeks (14 breakfasts) it's split exactly according to these percentages, shuffling the order at random. The percentages should add up to 100%.",
    "catalogo.mediaManana.intro": "Complete mid-morning snack options, not combined with anything else. Every 2 weeks (14 meals) it's split exactly according to these percentages, shuffling the order at random. The percentages should add up to 100%.",
    "catalogo.merienda.intro": "Complete afternoon snack options, not combined with anything else. Every 2 weeks (14 snacks) it's split exactly according to these percentages, shuffling the order at random. The percentages should add up to 100%.",
    "catalogo.cerrado.intro": "These go whole, not combined with carbs or veg. The whole group appears with the block's frequency; within it, which dish comes up is drawn at random.",
    "catalogo.especial.intro": "They don't compete for a protein slot: they layer on top of whatever meal comes up that day.",
    "catalogo.especial.extraNote": "Modifier: mixed 50/50 with the day's carb",
