    "privacidad.titulo": "Privacy policy — FoodDraft",
    "privacidad.actualizado": "Last updated: October 25, 2026",
    "privacidad.responsableHeader": "Data controller",
    "privacidad.responsableTexto": "Pablo Díaz Blanco, Spain.<br />Contact: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "privacidad.datosHeader": "What data we collect",
    "privacidad.datosCuenta": "<strong>Account</strong>: email and, if you sign in with Google, your profile photo.",
    "privacidad.datosPerfil": "<strong>Profile data</strong>: age, height, weight, sex, activity level and usual training, nutritional goal.",
    "privacidad.datosSeguimiento": "<strong>Tracking</strong>: weigh-in history, generated menus, catalog of foods and dishes you create, what you note down in your pantry and your workouts.",
    "privacidad.datosFotos": "<strong>Photos, pantry and text sent to the AI</strong>: if you use the photo reader, the image is sent to Gemini (Google) to read the nutritional data. If you use “What do I cook?”, whatever you choose to include is sent to Gemini: a photo of ingredients, the text you type and, if you leave the box ticked, the list of what you have in your pantry (the name of each food and an approximate amount). It is sent only to prepare the answer and <strong>is not stored</strong> on any FoodDraft server — it is discarded after processing.",
    "privacidad.paraQueHeader": "What it's used for",
    "privacidad.paraQueTexto": "Solely to provide the service: generating your menus, calculating your nutritional goals and tracking your weight. It is not used for advertising and is not sold to third parties.",
    "privacidad.baseLegalHeader": "Legal basis",
    "privacidad.baseLegalTexto": "Performance of the service you request when creating an account (GDPR art. 6.1.b) and, for photos, what you send to the AI and period data (health data), your explicit consent (GDPR art. 6.1.a and 9.2.a) when you voluntarily use those features.",
    "privacidad.conQuienHeader": "Who it's shared with",
    "privacidad.conQuienFirebase": "<strong>Google Firebase</strong> (authentication, database, anti-abuse protection, notifications and, via Gemini, photo reading and recipe generation), as data processor, with its own security and international data transfer safeguards.",
    "privacidad.conQuienStripe": "<strong>Stripe</strong>, only if you take out a paid subscription, to handle the charge (no health data is shared with it, only what's needed to process the payment).",
    "privacidad.conQuienNadie": "Nothing is shared with anyone else.",
    "privacidad.cuantoTiempoHeader": "How long it's kept",
    "privacidad.cuantoTiempoTexto": "For as long as your account exists. You can delete it completely, along with all your data, from the app at any time (Settings → Delete account).",
    "privacidad.derechosHeader": "Your rights",
    "privacidad.derechosTexto": "Access, rectification, erasure, objection, portability and restriction of processing. You can exercise them by deleting your account directly from the app, or by writing to <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>.",
    "privacidad.seguridadHeader": "Security",
    "privacidad.seguridadTexto": "Data travels encrypted and is protected by access rules that ensure each person can only see and modify their own.",
    "privacidad.cambiosHeader": "Changes to this policy",
    "privacidad.cambiosTexto": "If this policy changes significantly, you'll be notified within the app itself.",
    "privacidad.volver": "← Back to FoodDraft",

    "terminos.titulo": "Terms of use — FoodDraft",
    "terminos.actualizado": "Last updated: October 14, 2026",
    "terminos.quienesSomosHeader": "Who we are",
    "terminos.quienesSomosTexto": "FoodDraft is a service operated by Pablo Díaz Blanco, Spain.<br />Contact: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "terminos.queEsHeader": "What the service is",
    "terminos.queEsTexto": "FoodDraft generates weekly menus from your own dishes, calculates approximate nutritional goals and tracks your weight. <strong>Calorie, macro and goal calculations are approximate estimates</strong> based on general-use formulas (such as Mifflin-St Jeor) — they don't replace the advice of a doctor, dietitian or health professional. If in doubt or you have a medical condition, always consult a professional.",
    "terminos.tuCuentaHeader": "Your account",
    "terminos.tuCuentaTexto": "The service is for personal use. You're responsible for keeping your password secure and for your account's activity. You can delete it completely at any time from the app (Settings → Delete account).",
    "terminos.suscripcionHeader": "Paid subscription",
    "terminos.suscripcionTexto": "If you take out the paid version, billing is handled through Stripe. You can cancel at any time from your subscription management portal — cancellation takes effect at the end of the period already paid for, with no extra charges. When you cancel, premium features stop being available, but your data and the rest of the app remain intact.",
    "terminos.responsabilidadHeader": "Liability",
    "terminos.responsabilidadTexto": "You use the app at your own risk. We don't guarantee specific health, weight or body-composition results — the app is a support tool for organizing your diet, not a medical treatment. To the extent permitted by law, no liability is assumed for decisions made based on the information the app provides.",
    "terminos.usoIndebidoHeader": "Misuse",
    "terminos.usoIndebidoTexto": "We reserve the right to suspend or cancel an account in case of misuse of the service (for example, attempts to abuse the AI-powered features, or unauthorized access to third-party accounts).",
    "terminos.propiedadHeader": "Intellectual property",
    "terminos.propiedadTexto": "FoodDraft — the app, its code, design and texts — is owned by Pablo Díaz Blanco and protected by intellectual property law. All rights reserved. You are granted a personal, limited, revocable, non-exclusive right to use the app while you have an account; this does not include copying, modifying, redistributing or using its code or content to build another service. The fact that the source code is publicly visible does not grant any licence to use it. The data you enter (your dishes, notes and profile) remains yours.",
    "terminos.cambiosHeader": "Changes to these terms",
    "terminos.cambiosTexto": "If they change significantly, you'll be notified within the app itself.",
    "terminos.leyAplicableHeader": "Governing law",
    "terminos.leyAplicableTexto": "These terms are governed by Spanish law.",
    "terminos.volver": "← Back to FoodDraft",

