    "perfilView.repartoComidas.titulo": "Repartiment d'àpats",
    "perfilView.repartoComidas.intro": "Tria quants àpats fas al dia i quin pes té cadascun sobre el teu objectiu diari — es fa servir tant per generar el menú com per a la teva fracció d'àpats completats del resum mensual. Dinar i Sopar hi són sempre presents.",
