    "preset.clasico-4.label": "Clàssic · 4 àpats",
    "preset.clasico-4.texto": "El repartiment amb més suport a la ciència de la crononutrició: concentra l'energia a la primera meitat del dia.",
    "preset.sin-merienda-3.label": "3 àpats · sense berenar",
    "preset.sin-merienda-3.texto": "Esmorzar, dinar i sopar, sense res entre hores — el patró de tota la vida, amb un àpat menys que el clàssic però mantenint una estructura clara al llarg del dia.",
    "preset.sin-desayuno-3.label": "3 àpats · sense esmorzar",
    "preset.sin-desayuno-3.texto": "Saltar-se l'esmorzar de manera habitual s'ha relacionat en alguns estudis amb més greix acumulat al fetge — no és motiu d'alarma, però convé saber-ho si ho fas cada dia.",
    "preset.intermitente-2.label": "2 àpats · dinar i sopar",
    "preset.intermitente-2.texto": "Dejuni intermitent: menys àpats, però més grans. Com menys àpats fas, més fàcil és acabar picant entre hores si no et sacien prou bé — vigila bé les racions. A més, l'evidència dona més suport a la versió amb el dinar avançat cap al matí que no pas tard.",
    "preset.cinco-5.label": "5 àpats · amb mig matí",
    "preset.cinco-5.texto": "Àpats més petits i repartits, per a qui prefereix no passar moltes hores seguides sense menjar. No és dels patrons amb més evidència darrere, però és una manera habitual i vàlida d'organitzar el dia.",
    "avisoCena": "Els sopars copiosos o molt tardans s'associen a pitjor control del sucre, pitjor descans i més risc de greix al fetge. Si pots, que el sopar no sigui ni el més pesat ni el més tardà del dia.",

