    "medidas.proximamente": "Properament",
    "medidas.texto": "Aquí podràs afegir plecs cutanis i mesures corporals (cintura, maluc...) per completar el seguiment més enllà del pes a la bàscula. De moment no cal — el seguiment de pes del costat ja cobreix l'essencial.",

    "documentos.intro": "Aquí es podran consultar documents que, sense ser necessaris perquè l'app funcioni, expliquen com funciona per dins — i busquen deixar clar que decisions com les fórmules, els percentatges o els llindars no estan posades a l'atzar.",
    "documentos.sinDocumentos": "Encara no hi ha documents afegits",
