    "catalogo.proteina.intro": "Cada proteïna especial ocupa un nombre fix d'àpats per setmana o per cicle de 2 setmanes. El pollastre no té regla pròpia: omple tot el que sobra, així que és la base natural del menú.",
    "catalogo.carbo.intro": "Se sortegen per probabilitat a cada àpat que no sigui un plat tancat. Els percentatges haurien de sumar 100%.",
    "catalogo.verdura.intro": "Se sortegen per probabilitat, igual que els carbohidrats. Els percentatges haurien de sumar 100%.",
    "catalogo.grasa.intro": "Opcions de greix (oli, alvocat, fruits secs, formatge...). Quan el motor d'objectius necessiti completar greix en un àpat, sortejarà entre aquests per probabilitat — si no n'afegeixes cap, continuarà fent servir oli d'oliva per defecte.",
    "catalogo.desayuno.intro": "Opcions completes d'esmorzar, sense combinar amb res més. Cada 2 setmanes (14 esmorzars) es reparteix exactament segons aquests percentatges, barrejant l'ordre a l'atzar. Els percentatges haurien de sumar 100%.",
    "catalogo.mediaManana.intro": "Opcions completes de mig matí, sense combinar amb res més. Cada 2 setmanes (14 àpats) es reparteix exactament segons aquests percentatges, barrejant l'ordre a l'atzar. Els percentatges haurien de sumar 100%.",
    "catalogo.merienda.intro": "Opcions completes de berenar, sense combinar amb res més. Cada 2 setmanes (14 berenars) es reparteix exactament segons aquests percentatges, barrejant l'ordre a l'atzar. Els percentatges haurien de sumar 100%.",
    "catalogo.cerrado.intro": "Van sencers, sense combinar amb carbo ni verdura. El grup sencer apareix amb la freqüència del bloc; dins seu, se sorteja quin plat toca.",
    "catalogo.especial.intro": "No competeixen per un forat de proteïna: se superposen sobre l'àpat que toqui aquell dia.",
    "catalogo.especial.extraNote": "Modificador: barreja 50/50 amb el carbo del dia",
