    "privacidad.titulo": "Política de privacitat — FoodDraft",
    "privacidad.actualizado": "Última actualització: 25 d'octubre de 2026",
    "privacidad.responsableHeader": "Responsable del tractament",
    "privacidad.responsableTexto": "Pablo Díaz Blanco, Espanya.<br />Contacte: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "privacidad.datosHeader": "Quines dades es recullen",
    "privacidad.datosCuenta": "<strong>Compte</strong>: correu electrònic i, si inicies la sessió amb Google, la teva foto de perfil.",
    "privacidad.datosPerfil": "<strong>Dades de perfil</strong>: edat, alçada, pes, sexe, nivell d'activitat i entrenaments habituals, objectiu nutricional.",
    "privacidad.datosSeguimiento": "<strong>Seguiment</strong>: historial de pesades, menús generats, catàleg d'aliments i plats que creïs, el que apuntes al teu rebost i els teus entrenaments.",
    "privacidad.datosFotos": "<strong>Fotos, rebost i textos enviats a la IA</strong>: si fas servir el lector per foto, la imatge s'envia a Gemini (Google) per llegir les dades nutricionals. Si fas servir «Què cuino?», s'envia a Gemini el que decideixis incloure: una foto d'ingredients, el text que escriguis i, si deixes marcada la casella, la llista del que tens al rebost (el nom de cada aliment i una quantitat aproximada). Només s'envia per preparar la resposta i <strong>no s'emmagatzema</strong> en cap servidor de FoodDraft — es descarta després de processar-lo.",
    "privacidad.paraQueHeader": "Per a què es fan servir",
    "privacidad.paraQueTexto": "Únicament per prestar el servei: generar els teus menús, calcular els teus objectius nutricionals i portar el teu seguiment de pes. No es fan servir amb finalitats publicitàries ni es venen a tercers.",
    "privacidad.baseLegalHeader": "Base legal",
    "privacidad.baseLegalTexto": "L'execució del servei que sol·licites en crear un compte (art. 6.1.b RGPD) i, en el cas de les fotos, del que envies a la IA i de les dades del període (dades de salut), el teu consentiment explícit (art. 6.1.a i 9.2.a RGPD) en fer servir aquestes funcions de manera voluntària.",
    "privacidad.conQuienHeader": "Amb qui es comparteixen",
    "privacidad.conQuienFirebase": "<strong>Google Firebase</strong> (autenticació, base de dades, protecció antiabús, avisos i, via Gemini, lectura de fotos i generació de receptes), com a encarregat del tractament, amb les seves pròpies garanties de seguretat i transferència internacional de dades.",
    "privacidad.conQuienStripe": "<strong>Stripe</strong>, únicament si contractes una subscripció de pagament, per gestionar el cobrament (no se li comparteixen dades de salut, només el que cal per processar el pagament).",
    "privacidad.conQuienNadie": "No es comparteix res amb ningú més.",
    "privacidad.cuantoTiempoHeader": "Quant de temps es conserven",
    "privacidad.cuantoTiempoTexto": "Mentre el teu compte existeixi. Pots eliminar-lo completament, juntament amb totes les teves dades, des de l'app en qualsevol moment (Ajustos → Elimina el compte).",
    "privacidad.derechosHeader": "Els teus drets",
    "privacidad.derechosTexto": "Accés, rectificació, supressió, oposició, portabilitat i limitació del tractament. Els pots exercir eliminant el teu compte directament des de l'app, o escrivint a <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>.",
    "privacidad.seguridadHeader": "Seguretat",
    "privacidad.seguridadTexto": "Les dades viatgen xifrades i estan protegides per regles d'accés que garanteixen que cada persona només pot veure i modificar les seves.",
    "privacidad.cambiosHeader": "Canvis en aquesta política",
    "privacidad.cambiosTexto": "Si aquesta política canvia de forma rellevant, se n'avisarà dins de la mateixa app.",
    "privacidad.volver": "← Torna a FoodDraft",

    "terminos.titulo": "Termes d'ús — FoodDraft",
    "terminos.actualizado": "Última actualització: 14 d'octubre de 2026",
    "terminos.quienesSomosHeader": "Qui som",
    "terminos.quienesSomosTexto": "FoodDraft és un servei operat per Pablo Díaz Blanco, Espanya.<br />Contacte: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "terminos.queEsHeader": "Què és el servei",
    "terminos.queEsTexto": "FoodDraft genera menús setmanals a partir dels teus propis plats, calcula objectius nutricionals orientatius i porta un seguiment del teu pes. <strong>Els càlculs de calories, macros i objectius són estimacions orientatives</strong> basades en fórmules d'ús general (com Mifflin-St Jeor) — no substitueixen el consell d'un metge, nutricionista o professional de la salut. Davant de qualsevol dubte o condició mèdica, consulta sempre un professional.",
    "terminos.tuCuentaHeader": "El teu compte",
    "terminos.tuCuentaTexto": "El servei és d'ús personal. Ets responsable de mantenir segura la teva contrasenya i de l'activitat del teu compte. Pots eliminar-lo completament en qualsevol moment des de l'app (Ajustos → Elimina el compte).",
    "terminos.suscripcionHeader": "Subscripció de pagament",
    "terminos.suscripcionTexto": "Si contractes la versió de pagament, el cobrament es gestiona a través de Stripe. Pots cancel·lar en qualsevol moment des del portal de gestió de la teva subscripció — la cancel·lació s'aplica al final del període ja pagat, sense càrrecs addicionals. En cancel·lar, les funcions premium deixen d'estar disponibles, però les teves dades i la resta de l'app continuen intactes.",
    "terminos.responsabilidadHeader": "Responsabilitat",
    "terminos.responsabilidadTexto": "Fas servir l'app sota la teva pròpia responsabilitat. No garantim resultats concrets de salut, pes o composició corporal — l'app és una eina de suport per organitzar la teva alimentació, no un tractament mèdic. En la mesura permesa per la llei, no s'assumeix cap responsabilitat per decisions preses a partir de la informació que ofereix l'app.",
    "terminos.usoIndebidoHeader": "Ús indegut",
    "terminos.usoIndebidoTexto": "Ens reservem el dret de suspendre o cancel·lar un compte en cas d'ús indegut del servei (per exemple, intents d'abús de les funcions que fan servir intel·ligència artificial, o accés no autoritzat a comptes de tercers).",
    "terminos.propiedadHeader": "Propietat intel·lectual",
    "terminos.propiedadTexto": "FoodDraft — l'aplicació, el seu codi, el seu disseny i els seus textos — és propietat de Pablo Díaz Blanco i està protegida per la legislació de propietat intel·lectual. Tots els drets reservats. Se't concedeix un dret personal, limitat, revocable i no exclusiu per fer servir l'app mentre tinguis compte; això no inclou copiar, modificar, redistribuir ni fer servir el seu codi o els seus continguts per crear un altre servei. Que el codi font sigui visible públicament no suposa cap llicència d'ús. Les dades que introdueixes (els teus plats, les teves notes, el teu perfil) continuen sent teves.",
    "terminos.cambiosHeader": "Canvis en aquests termes",
    "terminos.cambiosTexto": "Si canvien de forma rellevant, se n'avisarà dins de la mateixa app.",
    "terminos.leyAplicableHeader": "Llei aplicable",
    "terminos.leyAplicableTexto": "Aquests termes es regeixen per la legislació espanyola.",
    "terminos.volver": "← Torna a FoodDraft",

