    "perfilView.intro": "Estes datos úsanse para calcular os teus obxectivos diarios de calorías e macros. Cámbiaos cando queiras — recalcúlanse sos ao gardar.",
    "perfilView.repartoComidas.titulo": "Reparto de comidas",
    "perfilView.repartoComidas.intro": "Elixe cantas comidas fas ao día e que peso ten cada unha sobre o teu obxectivo diario — úsase tanto para xerar o menú coma para a túa fracción de comidas completadas do resumo mensual. Comida e Cea están sempre presentes.",
