    "perfilView.eliminarCuenta.titulo": "Eliminar conta",
    "perfilView.eliminarCuenta.desc": "Borra a túa conta e todos os teus datos (alimentos, pratos, menús, peso, obxectivos) de forma permanente. Non se pode desfacer.",
    "perfilView.eliminarCuenta.boton": "Eliminar a miña conta",

    "preset.clasico-4.label": "Clásico · 4 comidas",
    "preset.clasico-4.texto": "O reparto con máis respaldo na ciencia da crononutrición: concentra a enerxía na primeira metade do día.",
    "preset.sin-merienda-3.label": "3 comidas · sen merenda",
    "preset.sin-merienda-3.texto": "Almorzo, comida e cea, sen nada entre horas — o patrón de toda a vida, cunha comida menos que o clásico pero mantendo unha estrutura clara ao longo do día.",
    "preset.sin-desayuno-3.label": "3 comidas · sen almorzo",
    "preset.sin-desayuno-3.texto": "Saltar o almorzo de forma habitual relacionouse nalgúns estudos con máis graxa acumulada no fígado — non é motivo de alarma, pero convén sabelo se o fas todos os días.",
    "preset.intermitente-2.label": "2 comidas · comida e cea",
    "preset.intermitente-2.texto": "Xaxún intermitente: menos comidas, pero máis grandes. Canto menos comidas fas, máis fácil é acabar picando entre horas se non che sacian ben — vixía ben as racións. Ademais, a evidencia respalda máis a versión coa comida adiantada cara á mañá que tarde.",
    "preset.cinco-5.label": "5 comidas · con media mañá",
    "preset.cinco-5.texto": "Comidas máis pequenas e repartidas, para quen prefire non pasar moitas horas seguidas sen comer. Non é dos patróns con máis evidencia detrás, pero é unha forma habitual e válida de organizar o día.",
    "avisoCena": "As ceas copiosas ou moi tardías asócianse a peor control do azucre, peor descanso e máis risco de graxa no fígado. Se podes, que a cea non sexa nin a máis pesada nin a máis tardía do día.",

