    "catalogo.proteina.intro": "Cada proteína especial ocupa un número fixo de comidas por semana ou por ciclo de 2 semanas. O polo non ten regra propia: enche todo o que sobra, así que é a base natural do menú.",
    "catalogo.carbo.intro": "Sortéanse por probabilidade en cada comida que non sexa un prato pechado. As porcentaxes deberían sumar 100%.",
    "catalogo.verdura.intro": "Sortéanse por probabilidade, igual que os carbohidratos. As porcentaxes deberían sumar 100%.",
    "catalogo.grasa.intro": "Opcións de graxa (aceite, aguacate, froitos secos, queixo...). Cando o motor de obxectivos necesite completar graxa nunha comida, sorteará entre estas por probabilidade — se non engades ningunha, seguirá usando aceite de oliva por defecto.",
    "catalogo.desayuno.intro": "Opcións completas de almorzo, sen combinar con nada máis. Cada 2 semanas (14 almorzos) repártese exactamente segundo estas porcentaxes, mesturando a orde ao azar. As porcentaxes deberían sumar 100%.",
    "catalogo.mediaManana.intro": "Opcións completas de media mañá, sen combinar con nada máis. Cada 2 semanas (14 comidas) repártese exactamente segundo estas porcentaxes, mesturando a orde ao azar. As porcentaxes deberían sumar 100%.",
    "catalogo.merienda.intro": "Opcións completas de merenda, sen combinar con nada máis. Cada 2 semanas (14 merendas) repártese exactamente segundo estas porcentaxes, mesturando a orde ao azar. As porcentaxes deberían sumar 100%.",
    "catalogo.cerrado.intro": "Van enteiros, sen combinar con carbo nin verdura. O grupo enteiro aparece coa frecuencia do bloque; dentro, sortéase cal prato toca.",
    "catalogo.especial.intro": "Non compiten por un oco de proteína: superpóñense sobre a comida que toque ese día.",
    "catalogo.especial.extraNote": "Modificador: mestura 50/50 co carbo do día",
