    "privacidad.titulo": "Política de privacidade — FoodDraft",
    "privacidad.actualizado": "Última actualización: 25 de outubro de 2026",
    "privacidad.responsableHeader": "Responsable do tratamento",
    "privacidad.responsableTexto": "Pablo Díaz Blanco, España.<br />Contacto: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "privacidad.datosHeader": "Que datos se recollen",
    "privacidad.datosCuenta": "<strong>Conta</strong>: correo electrónico e, se inicias sesión con Google, a túa foto de perfil.",
    "privacidad.datosPerfil": "<strong>Datos de perfil</strong>: idade, altura, peso, sexo, nivel de actividade e adestramentos habituais, obxectivo nutricional.",
    "privacidad.datosSeguimiento": "<strong>Seguimento</strong>: historial de pesadas, menús xerados, catálogo de alimentos e pratos que crees, o que apuntas na túa despensa e os teus adestramentos.",
    "privacidad.datosFotos": "<strong>Fotos, despensa e textos enviados á IA</strong>: se usas o lector por foto, a imaxe envíase a Gemini (Google) para ler os datos nutricionais. Se usas «Que cociño?», envíase a Gemini o que decidas incluír: unha foto de ingredientes, o texto que escribas e, se deixas marcada a caixa, a lista do que tes na despensa (o nome de cada alimento e unha cantidade aproximada). Só se envía para preparar a resposta e <strong>non se almacena</strong> en ningún servidor de FoodDraft — descártase despois de procesalo.",
    "privacidad.paraQueHeader": "Para que se usan",
    "privacidad.paraQueTexto": "Unicamente para prestar o servizo: xerar os teus menús, calcular os teus obxectivos nutricionais e levar o teu seguimento de peso. Non se usan con fins publicitarios nin se venden a terceiros.",
    "privacidad.baseLegalHeader": "Base legal",
    "privacidad.baseLegalTexto": "A execución do servizo que solicitas ao crear unha conta (art. 6.1.b RGPD) e, no caso das fotos, do que envías á IA e dos datos do período (datos de saúde), o teu consentimento explícito (art. 6.1.a e 9.2.a RGPD) ao usar esas funcións de forma voluntaria.",
    "privacidad.conQuienHeader": "Con quen se comparten",
    "privacidad.conQuienFirebase": "<strong>Google Firebase</strong> (autenticación, base de datos, protección antiabuso, avisos e, vía Gemini, lectura de fotos e xeración de receitas), como encargado do tratamento, coas súas propias garantías de seguridade e transferencia internacional de datos.",
    "privacidad.conQuienStripe": "<strong>Stripe</strong>, unicamente se contratas unha subscrición de pagamento, para xestionar o cobro (non se lle comparten datos de saúde, só o necesario para procesar o pagamento).",
    "privacidad.conQuienNadie": "Non se comparte nada con ninguén máis.",
    "privacidad.cuantoTiempoHeader": "Canto tempo se conservan",
    "privacidad.cuantoTiempoTexto": "Mentres a túa conta exista. Podes eliminala por completo, xunto con todos os teus datos, desde a app en calquera momento (Axustes → Eliminar conta).",
    "privacidad.derechosHeader": "Os teus dereitos",
    "privacidad.derechosTexto": "Acceso, rectificación, supresión, oposición, portabilidade e limitación do tratamento. Podes exercelos eliminando a túa conta directamente desde a app, ou escribindo a <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>.",
    "privacidad.seguridadHeader": "Seguridade",
    "privacidad.seguridadTexto": "Os datos viaxan cifrados e están protexidos por regras de acceso que garanten que cada persoa só pode ver e modificar os seus.",
    "privacidad.cambiosHeader": "Cambios nesta política",
    "privacidad.cambiosTexto": "Se esta política cambia de forma relevante, avisarase dentro da propia app.",
    "privacidad.volver": "← Volver a FoodDraft",

    "terminos.titulo": "Termos de uso — FoodDraft",
    "terminos.actualizado": "Última actualización: 14 de outubro de 2026",
    "terminos.quienesSomosHeader": "Quen somos",
    "terminos.quienesSomosTexto": "FoodDraft é un servizo operado por Pablo Díaz Blanco, España.<br />Contacto: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "terminos.queEsHeader": "Que é o servizo",
    "terminos.queEsTexto": "FoodDraft xera menús semanais a partir dos teus propios pratos, calcula obxectivos nutricionais orientativos e leva un seguimento do teu peso. <strong>Os cálculos de calorías, macros e obxectivos son estimacións orientativas</strong> baseadas en fórmulas de uso xeral (como Mifflin-St Jeor) — non substitúen o consello dun médico, nutricionista ou profesional da saúde. Ante calquera dúbida ou condición médica, consulta sempre un profesional.",
    "terminos.tuCuentaHeader": "A túa conta",
    "terminos.tuCuentaTexto": "O servizo é de uso persoal. Es responsable de manter seguro o teu contrasinal e da actividade da túa conta. Podes eliminala por completo en calquera momento desde a app (Axustes → Eliminar conta).",
    "terminos.suscripcionHeader": "Subscrición de pagamento",
    "terminos.suscripcionTexto": "Se contratas a versión de pagamento, o cobro xestiónase a través de Stripe. Podes cancelar en calquera momento desde o portal de xestión da túa subscrición — a cancelación aplícase ao final do período xa pagado, sen cargos adicionais. Ao cancelar, as funcións premium deixan de estar dispoñibles, pero os teus datos e o resto da app seguen intactos.",
    "terminos.responsabilidadHeader": "Responsabilidade",
    "terminos.responsabilidadTexto": "Usas a app baixo a túa propia responsabilidade. Non garantimos resultados concretos de saúde, peso ou composición corporal — a app é unha ferramenta de apoio para organizar a túa alimentación, non un tratamento médico. Na medida permitida pola lei, non se asume responsabilidade por decisións tomadas a partir da información que ofrece a app.",
    "terminos.usoIndebidoHeader": "Uso indebido",
    "terminos.usoIndebidoTexto": "Reservámonos o dereito de suspender ou cancelar unha conta en caso de uso indebido do servizo (por exemplo, intentos de abuso das funcións que usan intelixencia artificial, ou acceso non autorizado a contas de terceiros).",
    "terminos.propiedadHeader": "Propiedade intelectual",
    "terminos.propiedadTexto": "FoodDraft — a aplicación, o seu código, o seu deseño e os seus textos — é propiedade de Pablo Díaz Blanco e está protexida pola lexislación de propiedade intelectual. Todos os dereitos reservados. Concédeseche un dereito persoal, limitado, revogable e non exclusivo para usar a app mentres teñas conta; isto non inclúe copiar, modificar, redistribuír nin usar o seu código ou os seus contidos para crear outro servizo. Que o código fonte sexa visible publicamente non supón ningunha licenza de uso. Os datos que introduces (os teus pratos, as túas notas, o teu perfil) seguen sendo teus.",
    "terminos.cambiosHeader": "Cambios nestes termos",
    "terminos.cambiosTexto": "Se cambian de forma relevante, avisarase dentro da propia app.",
    "terminos.leyAplicableHeader": "Lei aplicable",
    "terminos.leyAplicableTexto": "Estes termos réxense pola lexislación española.",
    "terminos.volver": "← Volver a FoodDraft",

