    "perfilView.intro": "Datu hauek zure eguneroko kaloria eta makro helburuak kalkulatzeko erabiltzen dira. Aldatu nahi duzunean — automatikoki berriz kalkulatzen dira gordetzean.",
    "perfilView.repartoComidas.titulo": "Otorduen banaketa",
    "perfilView.repartoComidas.intro": "Aukeratu egunean zenbat otordu egiten dituzun eta bakoitzak zure eguneroko helburuan zenbateko pisua duen — menua sortzeko eta hilabeteko laburpeneko betetako otorduen zatia kalkulatzeko erabiltzen da. Bazkaria eta Afaria beti daude.",
    "perfilView.recomendado": "Gomendatua",
    "perfilView.pesoDeCadaComida": "Otordu bakoitzaren pisua",
    "perfilView.suma": "Batura: % {n}",
    "perfilView.sumaAviso": " — % 100 izan behar du zehatz-mehatz",
    "perfilView.guardarCambios": "Gorde aldaketak",
    "perfilView.guardadoOk": "Profila eguneratu da — zure helburuak berriz kalkulatu dira. Menua fitxako \"Helburuak\" botoian ikus ditzakezu.",
    "perfilView.eliminarCuenta.titulo": "Ezabatu kontua",
    "perfilView.eliminarCuenta.desc": "Zure kontua eta zure datu guztiak (elikagaiak, platerak, menuak, pisua, helburuak) behin betiko ezabatzen ditu. Ezin da desegin.",
    "perfilView.eliminarCuenta.boton": "Ezabatu nire kontua",

    "preset.clasico-4.label": "Klasikoa · 4 otordu",
    "preset.clasico-4.texto": "krononutrizioaren zientzian oinarri gehien duen banaketa: energia egunaren lehen erdian kontzentratzen du.",
    "preset.sin-merienda-3.label": "3 otordu · askaririk gabe",
    "preset.sin-merienda-3.texto": "Gosaria, bazkaria eta afaria, orduen artean ezer gabe — betiko eredua, klasikoak baino otordu bat gutxiagorekin baina egunean zehar egitura garbia mantenduz.",
    "preset.sin-desayuno-3.label": "3 otordu · gosaririk gabe",
    "preset.sin-desayuno-3.texto": "Gosaria ohituraz saltatzea ikerketa batzuetan gibelean metatutako gantza gehiagorekin lotu izan da — ez da larritzeko modukoa, baina jakin egin behar da egunero egiten baduzu.",
    "preset.intermitente-2.label": "2 otordu · bazkaria eta afaria",
    "preset.intermitente-2.texto": "Baraualdi tartekatua: otordu gutxiago, baina handiagoak. Zenbat eta otordu gutxiago egin, orduan eta errazagoa da orduen artean pikoteatzen bukatzea ondo asetzen ez bazaituzte — zaindu ondo razioak. Gainera, ebidentziak gehiago babesten du bazkaria goizago aurreratzeko bertsioa, berandu baino.",
    "preset.cinco-5.label": "5 otordu · hamaiketakoarekin",
    "preset.cinco-5.texto": "Otordu txikiagoak eta banatuagoak, jan gabe ordu asko jarraian egon nahi ez duenarentzat. Ez da ebidentzia gehien duten ereduetakoa, baina eguna antolatzeko modu ohiko eta baliozkoa da.",
    "avisoCena": "Afari kopurutsuak edo oso berandukoak azukrearen kontrol okerragoarekin, atseden txarragoarekin eta gibeleko gantza gehiagoko arriskuarekin lotzen dira. Ahal baduzu, afaria ez izan egunaren otordurik astunena ez eta berandukoena.",

    "deleteAccount.palabraConfirmacion": "EZABATU",
    "deleteAccount.desc": "Honek zure kontua eta zure datu guztiak behin betiko ezabatzen ditu: elikagaiak, platerak, menuak, pisu-historiala eta helburuak. Ezin da desegin.",
