    "suggestMeals.guardarComoCerrado": "Gorde plater itxi gisa",

    "medidas.proximamente": "Laster",
    "medidas.texto": "Hemen larruazal-tolesturak eta gorputz-neurriak (gerria, aldakak...) gehitu ahal izango dituzu, balantzako pisutik haratago jarraipena osatzeko. Oraingoz ez da beharrezkoa — alboko pisuaren jarraipenak funtsezkoa jada betetzen du.",

    "documentos.intro": "Hemen, aplikazioa funtzionatzeko beharrezkoak ez diren arren barrutik nola funtzionatzen duen azaltzen duten dokumentuak kontsultatu ahal izango dira — eta formulak, ehunekoak edo atalaseak bezalako erabakiak ez daudela zoriz jarrita argi utzi nahi dute.",
    "documentos.sinDocumentos": "Oraindik ez dago dokumenturik gehituta",
    "documentos.sinDocumentos.desc": "Prest daudenean, aplikazioaren barne-funtzionamendua azaltzen eta justifikatzen duten dokumentuak hemen agertuko dira.",

    "evaluacion.definicion.direccionContraria": "Pisua igotzen ari da definizio-etapa batean. Zerbait puntualagatik izan liteke, baina defizita berrikustea komeni da.",
    "evaluacion.definicion.ineficaz": "Oso gutxi galtzen ari zara (% {magnitud}/astea) — nahiko estimulu duen erritmotzat jotzen den % {umbral} baino gutxiago.",
