    "evaluacion.definicion.aviso": "Zure galera-erritmoa (% {magnitud}/astea) goiko zonan dago, % {umbralAviso} eta % {umbralAccion} artean.",
    "evaluacion.definicion.optimo": "Zure galera-erritmoa (% {magnitud}/astea) gomendatutako tartearen barruan dago (% {umbralIneficaz}-% {umbralAccion}).",
    "evaluacion.volumen.direccionContraria": "Pisua jaisten ari da bolumen-etapa batean. Zerbait puntualagatik izan liteke, baina superabita berrikustea komeni da.",
    "evaluacion.volumen.ineficaz": "Oso gutxi irabazten ari zara (% {magnitud}/hilea) — aurrera egiteko beharrezkotzat jotzen den % {umbral} baino gutxiago.",
