    "catalogo.proteina.intro": "Proteina berezi bakoitzak astean edo 2 asteko zikloan otordu-kopuru finko bat hartzen du. Oilaskoak ez du bere araurik: geratzen den guztia betetzen du, beraz menuaren oinarri naturala da.",
    "catalogo.carbo.intro": "Plater itxia ez den otordu bakoitzean probabilitatearen arabera zozketatzen dira. Ehunekoek % 100 batu beharko lukete.",
    "catalogo.verdura.intro": "Probabilitatearen arabera zozketatzen dira, karbohidratoak bezala. Ehunekoek % 100 batu beharko lukete.",
    "catalogo.grasa.intro": "Gantza-aukerak (olioa, aguakatea, fruitu lehorrak, gazta...). Helburu-motorrak otordu batean gantza osatu behar duenean, hauen artean zozketatuko du probabilitatearen arabera — bat ere gehitzen ez baduzu, oliba-olioa erabiltzen jarraituko du lehenetsi gisa.",
    "catalogo.desayuno.intro": "Gosari osoen aukerak, besterik gabe konbinatu gabe. 2 astero (14 gosari) ehuneko hauen arabera zehatz-mehatz banatzen da, ordena ausaz nahastuz. Ehunekoek % 100 batu beharko lukete.",
    "catalogo.mediaManana.intro": "Hamaiketako osoen aukerak, besterik gabe konbinatu gabe. 2 astero (14 otordu) ehuneko hauen arabera zehatz-mehatz banatzen da, ordena ausaz nahastuz. Ehunekoek % 100 batu beharko lukete.",
    "catalogo.merienda.intro": "Askari osoen aukerak, besterik gabe konbinatu gabe. 2 astero (14 askari) ehuneko hauen arabera zehatz-mehatz banatzen da, ordena ausaz nahastuz. Ehunekoek % 100 batu beharko lukete.",
    "catalogo.cerrado.intro": "Osorik doaz, karbohidratorik edo barazkirik gabe konbinatuta. Talde osoa blokearen maiztasunarekin agertzen da; barruan, zein plater tokatzen den zozketatzen da.",
    "catalogo.especial.intro": "Ez dute proteina-lekurik lehiatzen: egun horretan tokatzen den otorduaren gainean gainjartzen dira.",
    "catalogo.especial.extraNote": "Modifikatzailea: egun horretako karbohidratoarekin 50/50 nahasten da",
