    "privacidad.titulo": "Pribatutasun-politika — FoodDraft",
    "privacidad.actualizado": "Azken eguneratzea: 2026ko urriaren 25a",
    "privacidad.responsableHeader": "Tratamenduaren arduraduna",
    "privacidad.responsableTexto": "Pablo Díaz Blanco, Espainia.<br />Kontaktua: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "privacidad.datosHeader": "Zein datu biltzen diren",
    "privacidad.datosCuenta": "<strong>Kontua</strong>: helbide elektronikoa eta, Googlerekin saioa hasten baduzu, zure profil-argazkia.",
    "privacidad.datosPerfil": "<strong>Profil-datuak</strong>: adina, altuera, pisua, sexua, jarduera-maila eta ohiko entrenamenduak, helburu nutrizionala.",
    "privacidad.datosSeguimiento": "<strong>Jarraipena</strong>: pisatzeen historiala, sortutako menuak, elikagaien katalogoa eta sortzen dituzun platerak, zure jakitokian apuntatzen duzuna eta zure entrenamenduak.",
    "privacidad.datosFotos": "<strong>IAra bidalitako argazkiak, jakitokia eta testuak</strong>: argazki bidezko irakurgailua erabiltzen baduzu, irudia Gemini-ra (Google) bidaltzen da datu nutrizionalak irakurtzeko. «Zer sukaldatu?» erabiltzen baduzu, sartzea erabakitzen duzuna bidaltzen zaio Gemini-ri: osagaien argazki bat, idazten duzun testua eta, laukia markatuta uzten baduzu, jakitokian daukazunaren zerrenda (elikagai bakoitzaren izena eta gutxi gorabeherako kantitatea). Erantzuna prestatzeko soilik bidaltzen da eta <strong>ez da gordetzen</strong> FoodDrafteko inongo zerbitzarian — prozesatu ondoren baztertzen da.",
    "privacidad.paraQueHeader": "Zertarako erabiltzen diren",
    "privacidad.paraQueTexto": "Zerbitzua emateko bakarrik: zure menuak sortzeko, zure helburu nutrizionalak kalkulatzeko eta zure pisuaren jarraipena eramateko. Ez dira publizitate-helburuetarako erabiltzen, ezta hirugarrenei saltzen ere.",
    "privacidad.baseLegalHeader": "Oinarri legala",
    "privacidad.baseLegalTexto": "Kontu bat sortzean eskatzen duzun zerbitzuaren betearazpena (DBEO 6.1.b art.) eta, argazkien, IAra bidaltzen duzunaren eta aldiaren datuen (osasun-datuak) kasuan, funtzio horiek borondatez erabiltzean ematen duzun berariazko baimena (DBEO 6.1.a eta 9.2.a art.).",
    "privacidad.conQuienHeader": "Norekin partekatzen diren",
    "privacidad.conQuienFirebase": "<strong>Google Firebase</strong> (autentifikazioa, datu-basea, abusuen aurkako babesa, jakinarazpenak eta, Gemini bidez, argazki-irakurketa eta errezeta-sorkuntza), tratamendu-arduradun gisa, bere segurtasun-bermeekin eta datuen nazioarteko transferentziarekin.",
    "privacidad.conQuienStripe": "<strong>Stripe</strong>, ordainpeko harpidetza bat kontratatzen baduzu bakarrik, kobrantza kudeatzeko (ez zaio osasun-daturik partekatzen, ordainketa prozesatzeko beharrezkoa dena bakarrik).",
    "privacidad.conQuienNadie": "Ez da ezer partekatzen beste inorekin.",
    "privacidad.cuantoTiempoHeader": "Zenbat denboraz gordetzen diren",
    "privacidad.cuantoTiempoTexto": "Zure kontua existitzen den bitartean. Guztiz ezaba dezakezu, zure datu guztiekin batera, aplikaziotik edonoiz (Ezarpenak → Ezabatu kontua).",
    "privacidad.derechosHeader": "Zure eskubideak",
    "privacidad.derechosTexto": "Sarbidea, zuzenketa, ezabapena, aurkakotasuna, eramangarritasuna eta tratamenduaren mugapena. Aplikaziotik zure kontua zuzenean ezabatuz erabil ditzakezu, edo <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a> helbidera idatziz.",
    "privacidad.seguridadHeader": "Segurtasuna",
    "privacidad.seguridadTexto": "Datuak zifratuta bidaiatzen dute eta pertsona bakoitzak bereak ikusi eta aldatu ahal izatea bermatzen duten sarbide-arauen bidez babestuta daude.",
    "privacidad.cambiosHeader": "Politika honetako aldaketak",
    "privacidad.cambiosTexto": "Politika honek modu esanguratsuan aldatzen bada, aplikazioaren barruan jakinaraziko da.",
    "privacidad.volver": "← Itzuli FoodDraft-era",

    "terminos.titulo": "Erabilera-baldintzak — FoodDraft",
    "terminos.actualizado": "Azken eguneratzea: 2026ko urriaren 14a",
    "terminos.quienesSomosHeader": "Nortzuk garen",
    "terminos.quienesSomosTexto": "FoodDraft Pablo Díaz Blanco-k, Espainian, kudeatutako zerbitzu bat da.<br />Kontaktua: <a href=\"mailto:draftedfood@gmail.com\">draftedfood@gmail.com</a>",
    "terminos.queEsHeader": "Zerbitzua zer den",
    "terminos.queEsTexto": "FoodDraft-ek zure platerekin asteroko menuak sortzen ditu, helburu nutrizional orientagarriak kalkulatzen ditu eta zure pisuaren jarraipena eramaten du. <strong>Kaloria, makro eta helburuen kalkuluak estimazio orientagarriak dira</strong>, erabilera orokorreko formuletan oinarrituta (Mifflin-St Jeor bezala) — ez dute ordezten mediku, elikadura-dietista edo osasun-profesional baten aholkua. Zalantzarik edo egoera mediko bat izanez gero, kontsultatu beti profesional batekin.",
    "terminos.tuCuentaHeader": "Zure kontua",
    "terminos.tuCuentaTexto": "Zerbitzua erabilera pertsonalerakoa da. Zure pasahitza seguru mantentzeaz eta zure kontuaren jarduerarako arduraduna zara. Guztiz ezaba dezakezu edonoiz aplikaziotik (Ezarpenak → Ezabatu kontua).",
    "terminos.suscripcionHeader": "Ordainpeko harpidetza",
    "terminos.suscripcionTexto": "Ordainpeko bertsioa kontratatzen baduzu, kobrantza Stripe bidez kudeatzen da. Zure harpidetzaren kudeaketa-atarian edonoiz utz dezakezu — ezeztapena jada ordaindutako epearen amaieran aplikatzen da, kargurik gehiago gabe. Ezeztatzean, premium eginbideak eskuragarri egoteari uzten diote, baina zure datuak eta aplikazioaren gainerakoa osorik jarraitzen dute.",
    "terminos.responsabilidadHeader": "Erantzukizuna",
    "terminos.responsabilidadTexto": "Aplikazioa zure erantzukizunpean erabiltzen duzu. Ez dugu osasun, pisu edo gorputz-konposizio emaitza zehatzik bermatzen — aplikazioa zure elikadura antolatzeko laguntza-tresna da, ez tratamendu mediko bat. Legeak baimentzen duen neurrian, ez da erantzukizunik onartzen aplikazioak ematen duen informazioan oinarritutako erabakiengatik.",
    "terminos.usoIndebidoHeader": "Erabilera desegokia",
    "terminos.usoIndebidoTexto": "Kontu bat eten edo ezeztatzeko eskubidea gordetzen dugu, zerbitzuaren erabilera desegokiaren kasuan (adibidez, adimen artifiziala erabiltzen duten eginbideez abusatzeko saiakerak, edo hirugarrenen kontuetara baimenik gabeko sarbidea).",
    "terminos.propiedadHeader": "Jabetza intelektuala",
    "terminos.propiedadTexto": "FoodDraft — aplikazioa, bere kodea, diseinua eta testuak — Pablo Díaz Blancorena da, eta jabetza intelektualaren legediak babesten du. Eskubide guztiak erreserbatuta. Aplikazioa erabiltzeko eskubide pertsonal, mugatu, errebokagarri eta esklusiboa ez dena ematen zaizu kontua duzun bitartean; horrek ez ditu barne hartzen kopiatzea, aldatzea, birbanatzea, ez eta bere kodea edo edukiak beste zerbitzu bat sortzeko erabiltzea ere. Iturburu-kodea publikoki ikusgai egoteak ez dakar erabilera-lizentziarik. Zuk sartzen dituzun datuak (zure platerak, zure oharrak, zure profila) zureak izaten jarraitzen dute.",
    "terminos.cambiosHeader": "Baldintza hauetako aldaketak",
    "terminos.cambiosTexto": "Modu esanguratsuan aldatzen badira, aplikazioaren barruan jakinaraziko da.",
    "terminos.leyAplicableHeader": "Legeria aplikagarria",
    "terminos.leyAplicableTexto": "Baldintza hauek Espainiako legeriaren mende daude.",
    "terminos.volver": "← Itzuli FoodDraft-era",

